SourceCode.Declaration:
/// <summary>
/// [success] false with [errorCode] `'PENDING'` means the batch job hasn't reached the point of
/// creating its own `DMFExecution` row yet - not a failure, just not ready; the app keeps polling
/// `HSMobileOpsCountingService::resolveExportExecution` on the same interval it polls anything
/// else. Any other [errorCode] is a real failure. [executionId] is set only when [success].
/// </summary>
[DataContractAttribute]
class HSMobileOpsResolveExportExecutionResponse
{
    boolean success;
    str     errorCode;
    str     executionId;


}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('ExecutionId')]
public str parmExecutionId(str _value = executionId)
{
    executionId = _value;
    return executionId;
}
